rows = []
def add(id, category, item, qty, unit, price=None, url=None, notes='', option='primary', evidence='published_price', shipping=None, shipping_note='Not verified for Alto, GA 30510; obtain at checkout/quote.'):
    rows.append(dict(id=id, category=category, item=item, quantity=qty, unit=unit,
        unit_price_usd=price, extended_price_usd=round(price*qty,2) if price is not None else None,
        price_status=evidence if price is not None else 'quote_required', source_url=url,
        selection=option, shipping_usd=shipping, shipping_note=shipping_note,
        notes=notes, purchase_status='Candidate only; not ordered or released'))

uss='https://ussolid.com/products/1-in-brass-motorized-ball-valve-fast-2-second-12-24-v-dc-24-v-ac-5-wire-auto-return-normally-closed-full-port-ip68-manual-override'
