add('W04-REF','Water','Gems LS-7 PN253175 published sensor cost reference',5,'each',87.25,'https://www.gemssensors.com/products/LS-7/253175','Manufacturer page price and 20-day lead time observed. Reference price only: exact part material/contact type, liquid compatibility and shallow-pan geometry have NOT been selected. Do not count as a released 5-switch solution.',option='budget_reference')
add('W06','Water','Sensor pockets, welded bosses, guards and adjustable mounting brackets',1,'set',notes='Five channels total, not five automatically identical sensors. Brackets must permit cleaning and tested trip settings; retain independent HH and LL shutdown path.')
add('W07','Water','Pan drain fitting and removable coarse slag basket',1,'assembly',notes='1 to 1.5-inch passage, pan low point, accessible catch basket and flush/cleanout. Do not rely on a fine screen at the pan drain: it can blind and flood the pan. Final port location must clear bearers and permit valve removal.')
add('W08','Water','Independent unvalved overflow return',1,'assembly',notes='Overflow crest nominal 825 mm. Preliminary 1.5-inch internal passage and separate continuously falling hose to tank; demonstrate capacity above maximum installed pump flow under partial fouling. Include anti-splash entry and cleanout. No shared closing valve with main drain.')
add('W09','Water','1-inch reinforced non-collapsing hose for pump suction/discharge',10,'foot',notes='Preliminary purchase allowance, length pending routing. Select actual hose against suction, media and temperature; protect from sparks. Include bend-radius allowance and air-gapped pan discharge above maximum liquid level.')
add('W10','Water','1.5-inch reinforced hose for drain and independent overflow',10,'foot',notes='Preliminary routing allowance. W01 has 1-inch ports: adapters do not enlarge its restriction. Keep separate cleanable returns, continuous gravity fall and no low traps. Length and hose type pending final plumbing layout.')
add('W11','Water','Service unions, adapters and hose tails',1,'set',notes='Provisional takeoff: 2 drain-valve unions; 4 pump hose adapters; 4 drain/overflow hose adapters; 2 pan bosses; 2 reservoir return fittings; 1 pickup fitting; 1 cleanout fitting. Verify material and thread standards, avoid unnecessary elbows, then price exact parts. Do not order this as an undefined kit.')
add('W12','Water','Stainless hose clamps',16,'each',notes='Provisional: four pump hose ends plus four gravity-return hose ends, two clamps per end where barb length permits. Choose correctly sized all-stainless clamps after hose OD/barbs are set; do not double-clamp a barb too short for it.')
add('W13','Water','Clarified pickup strainer and service isolation',1,'assembly',notes='Must be pump-approved mesh/free area, accessible without disturbing storage. Coarse filtration does not remove abrasive fines. Coordinate whether BP2054 package already includes the required strainer to avoid double-counting.')
add('W14','Water','Air-gap return bracket, vent, cleanout plugs and gaskets',1,'set',notes='No sealed/pressurized tank. Vent cannot be a small blocked hole; verify refill/drain displacement airflow and accessible tank cleaning. Compatible gaskets and two cleanout access points minimum (pan and tank).')
